const uint lane = thread_index_in_simdgroup;
const uint row0 = (threadgroup_position_in_grid.x * 4 + simdgroup_index_in_threadgroup) * 2;
float acc[2] = {0.f, 0.f};
for (int k0 = lane * 32; k0 < K; k0 += 1024) {
    uint4 w[2];
    float s[2], b[2];
    #pragma unroll
    for (int r = 0; r < 2; r++) {
        uint n = row0 + r;
        if (n >= (uint)N) n = N - 1;  // clamp; result discarded
        w[r] = ld4(wq + n * (K / 8) + (k0 >> 3));
        s[r] = float(scales[n * (K / 64) + (k0 >> 6)]);
        b[r] = float(biases[n * (K / 64) + (k0 >> 6)]);
    }
    float xp[32];
    float xs = 0.f;
    for (int j = 0; j < 4; j++) {
        float sc = 1.f;
        for (int i = 0; i < 8; i++) {
            float v = float(x[k0 + j * 8 + i]);
            xs += v;
            xp[j * 8 + i] = v * sc;
            sc *= 0.0625f;
        }
    }
    #pragma unroll
    for (int r = 0; r < 2; r++) {
        float d = 0.f;
        for (int i = 0; i < 8; i++) {
            const uint m = 0xFu << (4 * i);
            d += xp[i] * float(w[r].x & m);
            d += xp[8 + i] * float(w[r].y & m);
            d += xp[16 + i] * float(w[r].z & m);
            d += xp[24 + i] * float(w[r].w & m);
        }
        acc[r] += s[r] * d + b[r] * xs;
    }
}
for (int r = 0; r < 2; r++) {
    float t = simd_sum(acc[r]);
    if (lane == 0 && row0 + r < (uint)N) out[row0 + r] = half(t);
}
